for _ in range(int(input())):
	n = int(input())
	l = list(map(int, input().split()))
	(b, w) = (n, 1)
	for i in range(n):
		a = [0] * n
		a[i] = 1
		for j in range(i):
			if l[j] > l[i]:
				a[j] = 1
		for j in range(i + 1, n):
			if l[j] < l[i]:
				a[j] = 1
		for j in range(i):
			if a[j] == 1:
				for z in range(i, n):
					if l[z] < l[j]:
						a[z] = 1
		for j in range(i + 1, n):
			if a[j] == 1:
				for y in range(i):
					if l[j] < l[y]:
						a[y] = 1
		f = a.count(1)
		w = max(f, w)
		b = min(f, b)
	print(b, w)
